do $$ begin create role anon nologin; create role authenticated nologin; exception when duplicate_object then null; end $$;
create schema if not exists auth;
create table if not exists auth.users (id uuid primary key default gen_random_uuid(), email text);
create or replace function auth.uid() returns uuid language sql stable as $$ select null::uuid $$;
create table public.customers (id bigint generated always as identity primary key, email text not null, name text);
create table public.orders (id bigint generated always as identity primary key, customer_id bigint references public.customers(id), total_cents int not null, status text not null default 'pending', created_at timestamptz default now());
create table public.order_items (id bigint generated always as identity primary key, order_id bigint references public.orders(id), sku text, quantity int);
create table public.invoices (id bigint generated always as identity primary key, order_id bigint, owner_id uuid, amount_cents int);
alter table public.invoices disable row level security;
create policy "Owners can read invoices" on public.invoices for select using (owner_id = auth.uid());
create table public.profiles (id uuid primary key, username text, avatar_url text);
alter table public.profiles enable row level security;
create policy "Users can view own profile" on public.profiles for select using (auth.uid() = id);
create table public.posts (id bigint generated always as identity primary key, author_id uuid, title text, published boolean default false);
alter table public.posts enable row level security;
create policy "Anyone can read published posts" on public.posts for select to authenticated using (published);
create policy "Authors can read own posts" on public.posts for select to authenticated using (author_id = auth.uid());
create view public.customer_summary with (security_invoker = false) as select c.id, c.email, count(o.id) as orders, sum(o.total_cents) as lifetime_cents from public.customers c left join public.orders o on o.customer_id = c.id group by c.id;
create function public.handle_new_user() returns trigger language plpgsql security definer as $$ begin insert into public.profiles (id) values (new.id); return new; end $$;
insert into public.customers (email, name) select 'user' || g || '@example.com', 'Customer ' || g from generate_series(1, 240) g;
insert into public.orders (customer_id, total_cents, status, created_at) select 1 + (g % 240), 500 + (g * 37 % 20000), (array['pending','paid','refunded'])[1 + g % 3], now() - (g || ' minutes')::interval from generate_series(1, 1800) g;
insert into public.order_items (order_id, sku, quantity) select 1 + (g % 1800), 'SKU-' || (g % 90), 1 + g % 4 from generate_series(1, 5200) g;
insert into public.invoices (order_id, amount_cents) select g, 1000 + g from generate_series(1, 600) g;
